users = list_users({})
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

day_results = for date in dates {
    avails = for user in users {
        a = get_availability({ user_id: user.id, date: date })
        b = a.busy if "busy" in a else null
        return b if b != null else []
    }
    valid = for start in list.range(540, 961, 30) {
        end = start + 60
        user_overlap = for busylist in avails {
            ivs = for iv in busylist {
                bs = number.parse(text.split(iv.start, ":")[0]) * 60 + number.parse(text.split(iv.start, ":")[1]) if iv.start != null and "start" in iv else 0
                be = number.parse(text.split(iv.end, ":")[0]) * 60 + number.parse(text.split(iv.end, ":")[1]) if iv.end != null and "end" in iv else 1440
                return bs < end and start < be
            }
            return true in ivs
        }
        skip if true in user_overlap
        return { start: start, end: end }
    }
    return { date: date, slot: valid[0] } if valid != [] else null
}

found = for r in day_results {
    skip if r == null
    return r
}
assert(found != [], "no slot found in the week")
first = found[0]
base = time.parse(first.date + "T00:00:00Z")
start_ms = base + first.slot.start * 60000
end_ms = base + first.slot.end * 60000
res = submit_result({ answer: { start: time.format(start_ms), end: time.format(end_ms) } })
return { start: time.format(start_ms), end: time.format(end_ms), recorded: res.recorded }

